function validate(input) {
  const [{ Visits = [], Transactions = [] }] = input;
  if (Visits.length === 0) return 'Visits has at least one row.';
  const visits = new Set();
  for (const [user, day] of Visits) {
    if (user === null || day === null) return 'Every visit needs a user_id and a visit_date.';
    const key = `${user}/${day}`;
    if (visits.has(key)) return `User ${user} visits twice on ${day}.`;
    visits.add(key);
  }
  for (const [user, day, amount] of Transactions) {
    if (user === null || day === null || amount === null) return 'Every transaction needs a user_id, a transaction_date and an amount.';
    if (!visits.has(`${user}/${day}`)) return `User ${user} has a transaction on ${day} without a visit.`;
  }
  return null;
}

