function generate(rand, size) {
  const small = size === 'small';
  const dayText = offset => new Date(Date.UTC(2020, 0, 1) + offset * 86400000).toISOString().slice(0, 10);
  const users = small ? 4 : 300, days = small ? 4 : 30;
  const pairs = [];
  for (let u = 1; u <= users; u++) for (let d = 0; d < days; d++) pairs.push([u, dayText(d)]);
  for (let i = pairs.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pairs[i], pairs[j]] = [pairs[j], pairs[i]]; }
  const Visits = pairs.slice(0, small ? 1 + Math.floor(rand() * 8) : 1500);
  // A few "busy" visits collect most transactions, so counts have gaps and a long tail.
  const busy = Visits.slice(0, Math.max(1, Math.floor(Visits.length / 10)));
  const Transactions = [];
  const count = small ? Math.floor(rand() * 9) : 1500;
  const amounts = [1, 7, 22, 33, 120];
  for (let i = 0; i < count; i++) {
    const [user, day] = rand() < 0.5 ? busy[Math.floor(rand() * busy.length)] : Visits[Math.floor(rand() * Visits.length)];
    Transactions.push([user, day, small ? amounts[Math.floor(rand() * amounts.length)] : 1 + Math.floor(rand() * 500)]);
  }
  return [{ Visits, Transactions }];
}
